sys_script.script:
(function validateQuantity() {
    var quantity = parseInt(current.getValue('quantity'), 10);

    gs.debug('[Retail Store Assistant] Validate Quantity: checking transaction quantity value: ' + current.getValue('quantity'));

    if (isNaN(quantity) || quantity <= 0) {
        gs.error('[Retail Store Assistant] Validate Quantity: rejected — quantity must be positive, got: ' + current.getValue('quantity'));
        gs.addErrorMessage('Inventory Transaction rejected: quantity must be a positive integer greater than zero.');
        current.setAbortAction(true);
        return;
    }

    // Ensure stored value is the clean integer
    current.setValue('quantity', quantity.toString());
    gs.debug('[Retail Store Assistant] Validate Quantity: passed — quantity=' + quantity);
})();
